SELECT u.* FROM sys_user u
WHERE u.tenant_id = #{tenantId} AND u.delete_flag = 0
 AND username LIKE CONCAT('%', CAST(#{username} AS VARCHAR), '%')
 AND name LIKE CONCAT('%', CAST(#{name} AS VARCHAR), '%')
 AND u.phone = #{phone}
 AND u.email = #{email}
 AND u.status = #{status}

    AND EXISTS (
        SELECT 1 FROM sys_user_org uo
        WHERE uo.tenant_id = #{tenantId}
          AND uo.user_id = u.id
          AND uo.delete_flag = 0
          AND uo.org_id IN

              #{orgId}

    )

ORDER BY u.created_at DESC, u.id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM sys_user u
WHERE u.tenant_id = #{tenantId} AND u.delete_flag = 0
 AND username LIKE CONCAT('%', CAST(#{username} AS VARCHAR), '%')
 AND name LIKE CONCAT('%', CAST(#{name} AS VARCHAR), '%')
 AND u.phone = #{phone}
